function validateIP(rule, value, callback) {
  if (!value) {
    callback(new Error("请输入IP地址"));
  } else {
    const ipPattern = /^(25[0-5]|2[0-4]\d|[0-1]?\d?\d)(\.(25[0-5]|2[0-4]\d|[0-1]?\d?\d)){3}$/;
    if (!ipPattern.test(value)) {
      callback(new Error("请输入有效的IP地址"));
    } else {
      callback();
    }
  }
}
