    maskPassword(password) {
      return '*'.repeat(password.length); // Replace with your own masking logic

    },
    toggleShowPassword(row) {
      row.showPassword = !row.showPassword;
    },
    // 查询字典
    getDictData() {
      this.$http
        .get(this.$url.url_5000 + "/model_view/type_select", {
          params: {
            mine_id: '1',
            // id:''
          },
        })
        .then((response) => {
          if (response.data.code === 200) {
            console.log(response.data);
            this.access_type = response.data.vcr_way
            this.sub_type = response.data.equipment_type
            this.producer_type = response.data.manufacturer_type
            this.Mine_id_type = response.data.mine_list
            this.addUpdateForm.Mine_id=this.Mine_id_type[0].id
            // this.tableData = response.data.data;
            // this.pagelength = response.data.data_list.total_items;
          }
        })
        .catch(function (response) {
          console.log(response);
        });
    },
    // 获取表格数据
    getData() {
      // 查询列表数据， type_st:'1'
      this.$http
        .get(this.$url.url_5000 + "/ziguang_platform_info_view/ziguang_security_platform_data", {
          params: {
            type_st: '1',
            // id:''
          },
        })
        .then((response) => {
          if (response.data.code === 200) {
            console.log(response.data.data);
            this.tableData = response.data.data.map(v => {
              return { ...v, showPassword: false }
            })
            console.log(this.tableData)
            // this.pagelength = response.data.data_list.total_items;
            this.total = response.data.total
          }
        })
        .catch(function (response) {
          console.log(response);
        });
    },
    pagination() {
      alert(this.detailId)
      // this.detailsTableData2 = this.detailsTableData.slice((this.DTpageNum - 1) * this.DTpageSize, this.DTpageNum * this.DTpageSize);
    },
    handleCurrentChange(val) {
      this.DTpageNum = val;
      this.handleLookDetail(this.detailId);
    },
    handleSizeChange(val) {
      this.DTpageSize = val;
      this.handleLookDetail(this.detailId);
    },
    indexMethod(index) {
      return (this.pageNum - 1) * this.pageSize + 1 + index;
    },
    // 查看详情
    handleLookDetail(row) {
      this.detailsOpen = true;
      this.$http
        .get(this.$url.url_5000 + "/ziguang_platform_info_view/ziguang_security_platform_data", {
          params: {
            type_st: '2',
            id: row,
            page:this.DTpageNum,
            per_page:this.DTpageSize,
          },
        })
        .then((response) => {
          if (response.data.code === 200) {
            // console.log(response.data);
            this.detailsForm = { ...response.data.data, showPassword: false };
            this.detailsTableData = response.data.data.children;
            this.DTtotal = response.data.data.total;
            this.detailsTableData2 = this.detailsTableData.slice(0, this.DTpageSize);
          }
        })
        .catch(function (response) {
          console.log(response);
        });
    },
    // 新增按钮
    handleClickAdd() {
      this.addUpdateTitle = "新增紫光华智平台设备";
      this.addUpdateForm = {};
      this.addUpdateOpen = true;
      this.resetForm("addUpdateForm");
    },
    // 重置表单函数
    resetForm(formName) {
      this.$refs[formName].resetFields();
    },
    // 确认新增（修改）函数
    handleAddOk() {
      this.$refs.addUpdateForm.validate((valid) => {
        if (valid) {
          const loading = this.$loading({
            lock: true,
            text: "Loading",
            spinner: "el-icon-loading",
            background: "rgba(0, 0, 0, 0.7)",
          });
          if (this.addUpdateTitle == "新增紫光华智平台设备") {
            // this.addUpdateForm.vcr_name = '录像机'
            // 创建一个新的 FormData 对象
            const formData = new FormData();

            // 遍历 addUpdateForm 中的每个键值对，并添加到 formData 中
            Object.keys(this.addUpdateForm).forEach(key => {
              formData.append(key, this.addUpdateForm[key]);
            });
            this.$http.post(
              this.$url.url_5000 + "/ziguang_platform_info_view/ziguang_platform_add",
              formData,
              {
                headers: {
                  "Content-Type": "multipart/form-data",
                },
              }
            ).then(response => {
              if (response.data.code == 200) {
                this.$message({ type: 'success', message: response.data.msg })
                this.getData()
                this.addUpdateOpen = false;
                loading.close();
              } else {
                this.$message({ type: 'warning', message: response.data.msg })
                this.getData()
                this.addUpdateOpen = false;
                loading.close();
              }
            }).catch(rek => {
              this.$message({ type: 'error', message: "请求失败" })
              loading.close();
              // this.$message({ type: 'error', message: response.data.msg })
              // this.getData()
              // console.log(rek);
            })
          } else if (this.addUpdateTitle == "修改硬盘录像机") {
            // updateData(this.addUpdateForm)
            //   .then((response) => {
            //     this.$message({
            //       type: "success",
            //       message: "修改成功",
            //     });
            //     this.addUpdateOpen = false;
            //   })
            //   .catch((rek) => {
            //     console.log(rek);
            //     this.addUpdateOpen = false;
            //   });

            delete this.addUpdateForm.vcr_ip;
            delete this.addUpdateForm.vcr_port;
            delete this.addUpdateForm.vcr_username;
            delete this.addUpdateForm.ziguang_password;
            this.$http
              .get(this.$url.url_5000 + "/model_view/VCR_data_update", {
                params: {
                  type_st: '2',
                  // id: data.id
                  ...this.addUpdateForm
                },
              })
              .then((response) => {
                if (response.data.code === 200) {
                  // console.log(response.data);
                  this.$message({
                    type: 'success',
                    message: response.data.msg
                  })
                  this.getData();
                  this.addUpdateOpen = false;
                  loading.close();
                }
              })
              .catch(function (response) {
                console.log(response);
                loading.close();
              });
          }
        } else {
          this.$message({
            type: "warning",
            message: "验证不通过",
          });
          return false;
        }
      });
    },
    // 删除按钮
    handleDeleteOne(data) {
      this.$confirm("此操作将永久删除该条数据, 是否继续?", "提示", {
        confirmButtonText: "确定",
        cancelButtonText: "取消",
        type: "warning",
      })
        .then(() => {
          const formData = new FormData();
          formData.append('id', data.id)
          this.$http.post(
            this.$url.url_5000 + "/ziguang_platform_info_view/ziguang_security_platform_delete",
            formData,
            {
              headers: {
                "Content-Type": "multipart/form-data",
              },
            }
          ).then(response => {
            if (response.data.code == 200) {
              this.$message({ type: 'success', message: response.data.msg })
              this.getData()
            } else {
              this.$message({ type: 'warning', message: response.data.msg })
              this.getData()
            }
          }).catch(rek => {
            this.$message({ type: 'error', message: response.data.msg })
            // this.getData()
            // console.log(rek);
          })
        })
        .catch((error) => {
          console.log(error);
          this.$message({
            type: "info",
            message: "已取消删除",
          });
        });
    },
    // 修改按钮
    handleClickUpdate(data) {
      this.addUpdateTitle = "修改硬盘录像机";
      // this.addUpdateForm = data;
      // 获取当前条的信息
      this.$http
        .get(this.$url.url_5000 + "/model_view/VCR_data_update", {
          params: {
            type_st: '1',
            id: data.id
          },
        })
        .then((response) => {
          if (response.data.code === 200) {
            // console.log(response.data);
            this.addUpdateForm = response.data.data
            // this.addUpdateForm.ziguang_id = response.data.data.vcr_username
            // this.addUpdateForm.ziguang_host = response.data.data.vcr_ip
            // this.addUpdateForm.ziguang_port = response.data.data.vcr_port
            // this.addUpdateForm.ziguang_password = response.data.data.ziguang_password
            this.$set(this.addUpdateForm, 'ziguang_id', response.data.data.vcr_username);
            this.$set(this.addUpdateForm, 'ziguang_host', response.data.data.vcr_ip);
            this.$set(this.addUpdateForm, 'ziguang_port', response.data.data.vcr_port);
            this.$set(this.addUpdateForm, 'ziguang_password', response.data.data.ziguang_password);
            this.$set(this.addUpdateForm, 'vcr_type', (this.producer_type.find(v => v.value == response.data.data.vcr_type)).id);
            this.$set(this.addUpdateForm, 'vcr_way', (this.access_type.find(v => v.value == response.data.data.vcr_way)).id);
            // this.pagelength = response.data.data_list.total_items;
          }
        })
        .catch(function (response) {
          console.log(response);
        });
      this.addUpdateOpen = true;
    },
    // 数据同步
    handleUpdate() {
      this.$http.post(this.$url.url_5000 + '/model_view/manual_sync').then(response => {
        if (response.data.code == 200) {
          this.$message(
            {
              type: 'success',
              message: response.data.msg
            }
          )
          this.getData();
        } else {
          this.$message(
            {
              type: 'warning',
              message: response.data.msg
            }
          )
        }
      }).catch(rek => {
        console.log(rek);
      })
    }
  },
};
</script>

